class Solution {
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Map<Integer, List<Integer>> map = new HashMap<>();
        int[] vis = new int[n];

        // Build the graph
        for (int[] e : edges) {
            int a = e[0], b = e[1];
            map.computeIfAbsent(a - 1, key -> new ArrayList<>()).add(b - 1);
            map.computeIfAbsent(b - 1, key -> new ArrayList<>()).add(a - 1);
        }

        // Topological Sort
        int start = 0;
        Stack<Integer> st = new Stack<>();
        boolean[] visited = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                start = i;
                dfs(start, map, visited, st);
            }
        }

        // Calculate the time
        return calcTime(st, map, hasApple);
    }

    private void dfs(int u, Map<Integer, List<Integer>> map, boolean[] visited, Stack<Integer> st) {
        if (visited[u]) return;
        visited[u] = true;
        st.push(u);
        for (int v : map.getOrDefault(u, new ArrayList<>())) {
            dfs(v, map, visited, st);
        }
    }

    private int calcTime(Stack<Integer> st, Map<Integer, List<Integer>> map, boolean[] hasApple) {
        int res = 0;
        while (!st.isEmpty()) {
            int u = st.pop();
            if (st.isEmpty()) return res;
            int v = st.peek();
            if (!hasApple[u]) continue;
            res += 2; // Time to travel from u to v
            if (hasApple[v]) res += 2; // Time to travel from v to u
            if (map.containsKey(v) && map.get(v).contains(u)) continue;
            st.push(v);
        }
        return res + 2;
    }
}
