public class Solution {
    public static boolean hasAllCodes(String s, int k) {
        HashSet<String> set = new HashSet<>();
        int windowStart = 0;

        for (int windowEnd = 0; windowEnd < s.length(); windowEnd++) {
            String substring = s.substring(windowStart, windowEnd + 1);
            if (set.contains(substring)) { // Check if the substring is already present in the set
                return false;
            } else { // Add the substring to the set
                set.add(substring);

                // If the current window length equals k, move the window start to the right
                if (windowEnd - windowStart + 1 == k) {
                    windowStart++; // Increment the window start
                }
            }
        }

        // If the length of the set is equal to the possible number of k-length binary strings, return true
        return set.size() == 1 << k;
    }
}
