public class SteppingNumberGenerator {

    public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> steppingNumbers = new ArrayList<>();
        for (int num = low; num <= high; num++) {
            SteppingState state = new SteppingState(num);
            findSteppingNumbersHelper(num, leftNumbers(num), rightNumbers(num), steppingState, steppingNumbers);
        }
        return steppingNumbers;
    }

    private static void findSteppingNumbersHelper(int number, List<Integer> leftNumbers, List<Integer> rightNumbers,
                                                SteppingState state, List<Integer> steppingNumbers) {
        int lastDigit = number % 10;
        if (number == 0 || (state.canSkipNext() && (lastDigit == 0 || lastDigit == 9))) {
            return;
        }
        int next = lastDigit == 0 ? lastDigit + 1 : lastDigit - 1;
        int candidate = number * 10 + next;
        if (next >= 0 && next <= 9) {
            steppingState.pull(candidate);
            findSteppingNumbersHelper(candidate, leftNumbers, rightNumbers, steppingState, steppingNumbers);
            steppingState.push(candidate);
        }

        // Handle the case where we have exhausted one branch early
        if (leftNumbers.size() > rightNumbers.size()) {
            findSteppingNumbersHelper(number, leftNumbers, rightNumbers, steppingState, steppingNumbers);
        } else if (leftNumbers.size() < rightNumbers.size()) {
            findSteppingNumbersHelper(number, leftNumbers, rightNumbers, steppingState, steppingNumbers);
        }
    }

    private static List<Integer> leftNumbers(int num) {
        List<Integer> leftNumbers = new ArrayList<>();
        while (num > 0) {
            leftNumbers.add(num % 10);
            num /= 10;
        }
        return leftNumbers;
    }

    private static List<Integer> rightNumbers(int num) {
        List<Integer> rightNumbers = new ArrayList<>();
        while (num > 0) {
            rightNumbers.add(num % 10);
            num /= 10;
        }
        Collections.reverse(rightNumbers);
        return rightNumbers;
    }

    private static class SteppingState {
        private int value;
        private int[] nextNumbers = {0, 0, 0};
        private boolean[] canSkip; // Skip next if it would be out of bounds or zero.

        public SteppingState(int value) {
            this.value = value;
            initializeCanSkip();
        }

        private void initializeCanSkip() {
            canSkip = new boolean[3];
            canSkip[0] = (!isValidDigit(this.value - 1) && (this.value > 10 || this.value == 9));
            canSkip[1] = (!isValidDigit(this.value + 1) && (this.value >= 1));
            canSkip[2] = (!isValidDigit(this.value - 1));
        }

        public void push(int value) {
            if (!this.canSkip[0]) {
                this.value = value;
                this.nextNumbers[0] = this.value + 1;
            }
        }

        public void pull(int value) {
            if (!this.canSkip[1]) {
                this.value = value;
                this.nextNumbers[1] = this.value - 1;
            }
        }

        public boolean canSkipNext() {
            return canSkip[2];
        }

        private boolean isValidDigit(int num) {
            return (num >= 0) && (num <= 9);
        }
    }
