    public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low > high) {
            // Ensure low is always less than high
            int temp = low;
            low = high;
            high = temp;
        }

        // Initialize the list with the valid starting numbers
        for (int i = 0; i <= 9; ++i) {
            if ((i == 0 && low > 9) || (i == 9 && high < 0)) {
                continue;
            }
            helper(low, high, result, i);
        }

        // Convert the list to an immutable sorted list
        result.sort(Integer::compare);
        return result;
    }

    private static void helper(int low, int high, List<Integer> result, int current) {
        if (current >= low && current <= high) {
            result.add(current);
        }

        // Check the next and previous numbers
        if (current == 0) {
            helper(low, high, result, current + 1);
        } else {
            helper(low, high, result, current + 1);
            helper(low, high, result, current - 1);
        }
    }
}
