        for (int num : A) {
            if (!isPerfectSquare(num)) {
                return 0;
            }
        }

        // Generate permutations
        BigInteger count = generatePermutations(A, maxElement, new boolean[A.length], 0, new BigInteger[]{}).add(BigInteger.ONE).subtract(BigInteger.ONE);
        return count.intValueExact();
