import java.util.Stack;

public static int findSmallestInteger(int n) {
    if (n <= 9) {
        return n; // Single digit numbers are inherently the smallest.
    }

    Stack<Character> digitsStack = new Stack<>();
    while (n > 0) {
        digitsStack.push((char) (n % 10 + '0'));
        n /= 10;
    }

    boolean found = false;
    while (!found) {
        Stack<Character> tempStack = new Stack<>(digitsStack);
        char temp; // To hold character while peeking
        char prevMax = '9'; // Previous максималь digit

        while (!tempStack.isEmpty()) {
            temp = tempStack.pop();
            prevMax = Math.min(prevMax, temp);

            if (temp != prevMax) {
                found = true;
                break;
            }
        }

        if (found) {
            // Make a modification by replacing the previous max digit with the smallest next digit.
            for (char i = '0'; i <= prevMax; i++) {
                if (tempStack.contains(i) && Character.compare(temp, i) < 0) {
                    temp = i;
                    break;
                }
            }

            // Swap the found maximum with the smallest next digit.
            int i = tempStack.search((char) (temp + '0'));
            tempStack.set(i, temp);
            tempStack.set((i - 1 < 0) ? tempStack.size() - 1 : i - 1, prevMax);

            // Convert the stack back to an integer.
            int result = 0;
            while (!tempStack.isEmpty()) {
                result = result * 10 + tempStack.pop() - '0';
            }
            return result;
        } else {
            return -1; // No larger permutation possible.
        }
    }
}
