public static int findSmallestInteger(int n) {
    // Convert the number to a string to easily access the digits
    String numStr = Integer.toString(n);

    // Check for the case where n is already the smallest possible permutation
    if (isSmallestPermutation(numStr)) {
        return -1;
    }

    // Find the smallest digit to swap
    char smallestDigit = findSmallestDigit(numStr);

    // Find the position of the smallest digit
    int smallestDigitIndex = numStr.indexOf(smallestDigit);

    // Create a new string by swapping the smallest digit with the first digit to the right of it
    String result = swapDigits(numStr, smallestDigitIndex, 0);

    // Convert the result back to an integer and return
    int resultInt = Integer.parseInt(result);
    return resultInt;
}

private static boolean isSmallestPermutation(String num) {
    // Sort the string to check if it's a permutation of sorted digits
    String sortedNum = num.chars()
                                .sorted()
                                .mapToObj(c -> String.valueOf(c))
                                .collect(Collectors.joining());
    return sortedNum.equals(num);
}

private static char findSmallestDigit(String num) {
    for (char digit : num.toCharArray()) {
        if (digit > '0') {
            return digit;
        }
    }
    return '9'; // If all digits are '0', smallest digit is '9'
}

private static String swapDigits(String num, int i, int j) {
    char[] chars = num.toCharArray();
    char temp = chars[i];
    chars[i] = chars[j];
    chars[j] = temp;
    return new String(chars);
