private static class UglyIterator implements Iterator<Integer> {
    private int next = 1;
    private List<Integer> candidates;
    private PriorityQueue<Integer> heap;

    UglyIterator() {
        candidates = new ArrayList<>();
        candidates.add(2);
        candidates.add(3);
        candidates.add(5);

        heap = new PriorityQueue<>(100);
        heap.offer(1);
    }

    @Override
    public boolean hasNext() {
        return !heap.isEmpty();
    }

    @Override
    public Integer next() {
        if (!hasNext()) {
            throw new RuntimeException("No more elements");
        }

        int current = heap.poll();
        for (int candidate : candidates) {
            if (current % candidate == 0) {
                heap.offer(current * candidate);
            }
        }

        next = heap.peek();
        return current;
    }
}
