import java.util.List;

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new LinkedList<>();
    if (n < 1) return result;

    // Create a root node with value 1
    IntervalTreeNode root = new IntervalTreeNode(1);

    // Construct the interval tree to allow lexicographical order
    for (int i = 2; i <= n; i++) {
        int digit = i % 10;
        IntervalTreeNode parent = root;
        IntervalTreeNode current = parent.left;

        // Traverse the tree to find the correct position
        while (current != null && current.value < digit) {
            parent = current;
            current = current.right;
        }

        // Insert the new node into the correct position
        if (current == null) {
            parent.right = new IntervalTreeNode(digit);
        } else {
            current.value = digit;
        }
    }

    // Collect elements from the interval tree into the result list
    collectNodes(root.left, result);

    return result;
}

// Helper class to represent a node in the interval tree
class IntervalTreeNode {
    int value;
    IntervalTreeNode left;
    IntervalTreeNode right;

    public IntervalTreeNode(int val) {
        this.value = val;
        this.left = null;
        this.right = null;
    }
}

// Helper method to collect nodes from the interval tree into a list
void collectNodes(IntervalTreeNode node, List<Integer> result) {
    if (node == null) return;

    collectNodes(node.left, result);
    result.add(node.value);
    collectNodes(node.right, result);
}
