    StringBuilder reversed = new StringBuilder();
    String[] words = s.trim().split("\\s+");
    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word);
        for (int i = 0; i < reversedWord.length() / 2; i++) {
            char temp = reversedWord.charAt(i);
            reversedWord.setCharAt(i, reversedWord.charAt(reversedWord.length() - i - 1));
            reversedWord.setCharAt(reversedWord.length() - i - 1, temp);
        }
        if (reversedList.length() > 0) {
            reversed.append(" ");
        }
        reversed.append(reversedWord);
    }
    return reversed.toString();
}
